<?php
require 'includes/bootstrap.php';if(empty($_SESSION['role']))go('student_login.php');$role=$_SESSION['role'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='ask'&&$role==='student'){$subject=trim($_POST['subject']??'');$question=trim($_POST['question']??'');if($subject&&$question){$q=$pdo->prepare('INSERT INTO questions(student_id,subject,question) VALUES(?,?,?)');$q->execute([$_SESSION['user_id'],$subject,$question]);flash('Your question has been posted.');}else flash('Subject and question are required.');go('qa.php');}
 if($action==='answer'&&in_array($role,['faculty','admin'],true)){$id=(int)($_POST['question_id']??0);$answer=trim($_POST['answer']??'');if($answer){$check=$pdo->prepare('SELECT id FROM questions WHERE id=?');$check->execute([$id]);if($check->fetch()){$q=$pdo->prepare('INSERT INTO answers(question_id,faculty_id,admin_id,answer) VALUES(?,?,?,?)');$q->execute([$id,$role==='faculty'?$_SESSION['user_id']:null,$role==='admin'?$_SESSION['user_id']:null,$answer]);flash('Answer posted.');}}go('qa.php');}
}
$sql='SELECT q.*,s.name student_name FROM questions q JOIN student s ON s.id=q.student_id ORDER BY q.created_at DESC';$questions=$pdo->query($sql)->fetchAll();$ans=$pdo->prepare('SELECT a.*,f.name faculty_name,ad.username admin_name FROM answers a LEFT JOIN faculty f ON f.id=a.faculty_id LEFT JOIN admin ad ON ad.id=a.admin_id WHERE a.question_id=? ORDER BY a.created_at');
page_start('Questions and Answers');?>
<div class="vc-card"><h2>Questions &amp; Answers Forum</h2><p>Ask questions about your subjects and get help from faculty or the administrator.</p><?php if($role==='student'): ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="ask"><div class="form-group mb-3"><label>Subject</label><input class="form-control" name="subject" required maxlength="150"></div><div class="form-group mb-3"><label>Your question</label><textarea class="form-control" name="question" rows="4" required></textarea></div><button class="btn btn-primary">Post question</button></form><?php endif; ?></div>
<?php foreach($questions as $q): ?><div class="vc-card"><p><b><?=e($q['subject'])?></b> · Asked by <?=e($q['student_name'])?> · <?=e($q['created_at'])?></p><h4><?=nl2br(e($q['question']))?></h4><?php $ans->execute([$q['id']]);$answers=$ans->fetchAll();foreach($answers as $a): ?><div style="background:#f2f5fa;padding:15px;border-radius:8px;margin:12px 0"><b>Answer by <?=e($a['faculty_name']??('Admin '.($a['admin_name']??'')))?></b><p><?=nl2br(e($a['answer']))?></p><small><?=e($a['created_at'])?></small></div><?php endforeach; if(in_array($role,['faculty','admin'],true)): ?><form method="post" class="mt-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="answer"><input type="hidden" name="question_id" value="<?=$q['id']?>"><div class="form-group mb-2"><textarea class="form-control" name="answer" rows="2" placeholder="Write an answer..." required></textarea></div><button class="btn btn-sm btn-success">Submit answer</button></form><?php endif; ?></div><?php endforeach; if(!$questions): ?><div class="vc-card">No questions yet. Be the first to ask.</div><?php endif; ?><?php page_end(); ?>